\section{The mod-exponential sequence and its order}\label{sec:seq}

Throughout, $N \ge 1$ is an integer, $a \ge 1$ is coprime to $N$, and $m \ge 0$ is a
window length.

\begin{definition}[mod-exponential sequence]
For $x \in \mathbb{N}$ set $s_x = a^x \bmod N \in \{0,1,\dots,N-1\}$.
\end{definition}

\begin{definition}[order]
$\ord_N(a)$ is the multiplicative order of the class of $a$ in $\mathbb{Z}/N\mathbb{Z}$,
the least $d \ge 1$ with $a^d \equiv 1 \pmod N$.
\end{definition}

\begin{lemma}[finiteness of order]\label{lem:finord}
If $N>0$ and $\gcd(a,N)=1$, the class of $a$ in $\mathbb{Z}/N\mathbb{Z}$ has finite
order and $\ord_N(a) \ge 1$.
\end{lemma}

\begin{proof}
Euler's theorem gives $a^{\varphi(N)} \equiv 1 \pmod N$ with $\varphi(N) \ge 1$, so the
class of $a$ satisfies a nontrivial power relation and has finite positive order.
\end{proof}

\begin{theorem}[Collision Law]\label{thm:collision}
Let $N>0$, $\gcd(a,N)=1$, $d=\ord_N(a)$. For all $x,y \in \mathbb{N}$,
\[
s_y = s_x \iff y \equiv x \pmod d .
\]
\end{theorem}

\begin{proof}
$s_y = s_x$ is $a^y \equiv a^x \pmod N$, i.e.\ equality of powers of the class $g$ of
$a$. For $g$ of finite order $d$ in a monoid, $g^y = g^x$ iff $y \equiv x \pmod d$:
assuming $y \ge x$ and cancelling (legitimate, as $g$ is a unit) reduces to
$g^{y-x} = 1$, which by division with remainder and minimality of $d$ holds iff
$d \mid y-x$.
\end{proof}

Theorem~\ref{thm:collision} is elementary; everything below follows from taking it
seriously. It says that \emph{all} the equality structure of the sequence is the
arithmetic of the single integer $d$.

\section{Pattern words: structure and truncation}\label{sec:pattern}

\begin{definition}[first occurrence, pattern word]
For $x \in \mathbb{N}$ set $\first(x) = \min\{y \in \mathbb{N} : s_y = s_x\}$,
well defined since $x$ is a candidate. The \emph{pattern word of the length-$m$ window}
is
\[
w_{a,N,m}(x) = \begin{cases} \first(x), & x < m,\\ 0, & x \ge m.\end{cases}
\]
\end{definition}

The pattern word is the window with numerical values erased and only the collision
structure kept: for $x,y<m$, $w(x)=w(y)$ exactly when $s_x = s_y$. Every ``collision
feature'' --- distinct-value count, self-collision gap, longest repeat, run-length
profile, block structure --- is a function of $w$.

\begin{theorem}[Structure Theorem]\label{thm:structure}
Let $N>0$, $\gcd(a,N)=1$, $d=\ord_N(a)$. Then $\first(x) = x \bmod d$ for all $x$.
\end{theorem}

\begin{proof}
($\le$) Since $x \bmod d \equiv x \pmod d$, Theorem~\ref{thm:collision} gives
$s_{x \bmod d} = s_x$, so $\first(x) \le x \bmod d$.
($\ge$) Suppose $y < x \bmod d$ with $s_y = s_x$. Then $y \equiv x \pmod d$, so
$y \bmod d = x \bmod d$; but $y < x \bmod d < d$ gives $y \bmod d = y$, whence
$y = x \bmod d$, a contradiction.
\end{proof}

\begin{lemma}\label{lem:trunc}
For $x<m$ and $d \ge 1$, $x \bmod \min(m,d) = x \bmod d$.
\end{lemma}

\begin{proof}
If $d \le m$ then $\min(m,d)=d$. If $m \le d$ then $\min(m,d)=m$ and $x<m\le d$, so both
sides equal $x$.
\end{proof}

\begin{theorem}[Truncation Theorem]\label{thm:truncation}
Under the hypotheses of Theorem~\ref{thm:structure},
\[
w_{a,N,m}(x) = \begin{cases} x \bmod \min(m,\ord_N(a)), & x<m,\\ 0, & x \ge m,\end{cases}
\]
so $w_{a,N,m}$ depends on $(a,N)$ only through
$\min(m,\ord_N(a)) \in \{0,1,\dots,m\}$.
\end{theorem}

\begin{proof}
Immediate from Theorem~\ref{thm:structure} and Lemma~\ref{lem:trunc}.
\end{proof}

\begin{theorem}[Blindness Theorem]\label{thm:blind}
Let $N_1,N_2>0$ with $\gcd(a_i,N_i)=1$. If
$\min(m,\ord_{N_1}(a_1)) = \min(m,\ord_{N_2}(a_2))$ then
$w_{a_1,N_1,m} = w_{a_2,N_2,m}$; consequently
$F(w_{a_1,N_1,m}) = F(w_{a_2,N_2,m})$ for \emph{every} map $F$ defined on pattern words,
with values in an arbitrary set.
\end{theorem}

\begin{proof}
The first claim is Theorem~\ref{thm:truncation} with the two equal truncated orders
substituted; the second is functional application.
\end{proof}

\begin{remark}
The quantification is over \emph{all} functions on pattern words, computable or not, of
arbitrary complexity. No feature engineering, model class or quantity of data can
distinguish two instances satisfying the hypothesis, because the objects being
distinguished are literally equal.
\end{remark}

\subsection{The distinct-count feature}

\begin{definition}
$\dc(a,N,m) = \#\{a^x \bmod N : 0 \le x < m\}$.
\end{definition}

\begin{theorem}[exact law for the distinct count]\label{thm:dc}
For $N>0$, $\gcd(a,N)=1$: $\dc(a,N,m) = \min(m,\ord_N(a))$.
\end{theorem}

\begin{proof}
Let $d=\ord_N(a)$, $k=\min(m,d)$. For $x<m$, $s_x = s_{x \bmod d}$ and
$x \bmod d < k$, so the image of $\{0,\dots,m-1\}$ equals that of $\{0,\dots,k-1\}$. On
$\{0,\dots,k-1\}$ the map $x \mapsto s_x$ is injective: $s_x=s_y$ forces
$x \equiv y \pmod d$ and $x,y<k \le d$ forces $x=y$. Hence the image has $k$ elements.
\end{proof}

\begin{corollary}\label{cor:fresh}
If $m \le \ord_N(a)$ then $\dc(a,N,m)=m$: every value is fresh and the window has no
internal collision structure at all.
\end{corollary}

\section{The information bound}\label{sec:info}

\begin{definition}
$\mathcal{W}_m = \{w_{a,N,m} : N>0,\ \gcd(a,N)=1\}$, the set of all length-$m$ pattern
words over all bases and all moduli.
\end{definition}

\begin{theorem}[Information Bound]\label{thm:infobound}
$|\mathcal{W}_m| \le m+1$.
\end{theorem}

\begin{proof}
Let $\Phi_k(x) = x \bmod k$ for $x<m$ and $0$ otherwise. By
Theorem~\ref{thm:truncation}, every $w_{a,N,m}$ equals $\Phi_k$ for
$k = \min(m,\ord_N(a)) \in \{0,\dots,m\}$, so $\mathcal{W}_m$ lies in the image of a set
of size $m+1$.
\end{proof}

\begin{corollary}[bit budget]
The collision structure of a length-$m$ window carries at most $\log_2(m+1)$ bits about
$(a,N)$, uniformly in $N$.
\end{corollary}

For $m=256$ this is under $8.01$ bits, against the $\Theta(\log N)$ bits needed merely to
name a factor. The gap is not a matter of degree: no procedure can synthesize bits the
channel does not carry.

\begin{theorem}[Pigeonhole form]\label{thm:pigeon}
Let $T$ be a finite set of odd moduli with $|T| > m+1$. Then there are distinct
$N_1,N_2 \in T$ with $w_{2,N_1,m} = w_{2,N_2,m}$.
\end{theorem}

\begin{proof}
Each odd $N$ is positive and coprime to $2$. The map $N \mapsto \min(m,\ord_N(2))$ sends
$T$ into $\{0,\dots,m\}$, of size $m+1<|T|$; two distinct elements share an image, and
Theorem~\ref{thm:blind} equates their pattern words.
\end{proof}

\begin{corollary}[class-independent incompressibility]
For any $F$ defined on pattern words, $N \mapsto F(w_{2,N,m})$ is not injective on any
set of more than $m+1$ odd moduli.
\end{corollary}

A length-$256$ window cannot separate $258$ moduli, let alone identify a subtle
arithmetic property of $p-1$. The obstruction is independent of the labelling.

\section{The learning bridge: exact chance}\label{sec:auc}

\begin{definition}[AUC]
For finite nonempty $S$ (positives), $G$ (negatives) and a real score $f$, the tie-aware
rank definition of the area under the ROC curve is
\[
\AUC(S,G,f) = \frac{1}{|S||G|}\sum_{s\in S}\sum_{g\in G}
\Big(\mathbf 1\{f(g)<f(s)\} + \tfrac12 \mathbf 1\{f(g)=f(s)\}\Big).
\]
\end{definition}

\begin{theorem}[AUC Bridge]\label{thm:aucbridge}
If $f(s)=f(g)$ for all $s\in S$, $g \in G$, then $\AUC(S,G,f) = 1/2$ exactly.
\end{theorem}

\begin{proof}
Every summand is a tie, contributing $1/2$; the double sum is $|S||G|/2$, and dividing
by $|S||G|\ne 0$ gives $1/2$.
\end{proof}

\begin{lemma}[rank invariance]
For strictly increasing $g:\mathbb{R}\to\mathbb{R}$,
$\AUC(S,G,g\circ f) = \AUC(S,G,f)$.
\end{lemma}

\begin{proof}
Strict monotonicity preserves and reflects both $<$ and $=$, so every indicator is
unchanged.
\end{proof}

\begin{theorem}[No free lunch, abstract form]\label{thm:nfl}
Let $\mathcal{F}$ be a set of moduli on which the length-$m$ pattern word is constant.
Then for every real statistic $F$ of pattern words and all finite nonempty
$S,G \subseteq \mathcal{F}$,
\[
\AUC\big(S,G,\ N \mapsto F(w_{2,N,m})\big) = \tfrac12 .
\]
\end{theorem}

\begin{proof}
The score is constant on $\mathcal{F}$; apply Theorem~\ref{thm:aucbridge}.
\end{proof}

The theorem quantifies over labellings as well as features: the window does not merely
fail to detect smoothness, it fails to detect anything.

\section{Pollard's $p-1$: the weakness is real}\label{sec:pollard}

\begin{theorem}[correctness]\label{thm:pm1ok}
Let $p$ be prime with $p \mid N$, $p \nmid a$, and let $(p-1) \mid M$. Then
$p \mid \gcd(a^M-1, N)$.
\end{theorem}

\begin{proof}
Fermat gives $a^{p-1}\equiv 1 \pmod p$; writing $M=(p-1)k$ gives $a^M \equiv 1 \pmod p$,
so $p \mid a^M-1$, and $p \mid N$ by hypothesis.
\end{proof}

\begin{theorem}[exact divisibility criterion]\label{thm:criterion}
For $a \ge 1$, $r \ge 1$, $M \ge 0$:
$\;r \mid a^M - 1 \iff \ord_r(a) \mid M$.
\end{theorem}

\begin{proof}
$r \mid a^M-1$ says $g^M = 1$ for $g$ the class of $a$ in $\mathbb{Z}/r\mathbb{Z}$,
which by division with remainder and minimality of the order holds iff
$\ord(g) \mid M$.
\end{proof}

\begin{theorem}[failure]\label{thm:pm1fail}
Let $p,q$ be primes, $a \ge 1$, and suppose $\ord_p(a) \nmid M$ and
$\ord_q(a) \nmid M$. Then $\gcd(a^M-1, pq) = 1$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:criterion} neither $p$ nor $q$ divides $a^M-1$; as both are prime,
$a^M-1$ is coprime to each, hence to their product.
\end{proof}

These delimit exactly what the method sees: one bit per prime factor, namely whether the
local order divides $M$. Theorem~\ref{thm:criterion} shows this bit is the outcome of a
divisibility test involving the order, whose only known evaluation route is the
exponentiation $a^M \bmod N$ --- the method itself.

\subsection{Order arithmetic}

\begin{lemma}\label{lem:ordsub1}
If $r$ is prime and $r \nmid a$ then $\ord_r(a) \mid r-1$.
\end{lemma}

\begin{lemma}\label{lem:primedvd}
If $d \mid sr$ with $r$ prime and $d \nmid s$, then $r \mid d$.
\end{lemma}

\begin{proof}
Otherwise $\gcd(d,r)=1$, and $d \mid sr$ forces $d \mid s$.
\end{proof}

\begin{lemma}[order under reduction]\label{lem:ordred}
If $r \mid N$ then $\ord_r(a) \mid \ord_N(a)$.
\end{lemma}

\begin{proof}
Reduction $\mathbb{Z}/N\mathbb{Z}\to\mathbb{Z}/r\mathbb{Z}$ is a ring homomorphism
sending the class of $a$ to the class of $a$; the order of an image divides the order of
the element.
\end{proof}

\section{The explicit matched pair}\label{sec:pair}

Fix $B=20$, so
\[
M = \lcmop(1,\dots,20) = 232\,792\,560 = 2^4\cdot3^2\cdot5\cdot7\cdot11\cdot13\cdot17\cdot19,
\]
and set
\[
N_{\mathrm{smooth}} = 1009\cdot1019 = 1\,028\,171, \qquad
N_{\mathrm{general}} = 1019\cdot1039 = 1\,058\,741 .
\]
All three primes have $10$ bits, so the instances are size-matched; the two moduli share
the prime $1019$, which pins their window statistics together.

\begin{proposition}\label{prop:ord1019}
$509 \le \ord_{1019}(2)$.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:ordsub1}, $d := \ord_{1019}(2)$ divides $1018 = 2\cdot509$. If
$d \mid 2$ then $4 \equiv 1 \pmod{1019}$, false. By Lemma~\ref{lem:primedvd} with $s=2$,
$r=509$, we get $509 \mid d$. (In fact $d = 1018$.)
\end{proof}

\begin{proposition}\label{prop:nd1019}
$\ord_{1019}(2) \nmid M$.
\end{proposition}

\begin{proof}
Otherwise $d \mid \gcd(M,1018) = 2$ (since the prime $509>20$ does not divide $M$), so
$4 \equiv 1 \pmod{1019}$, false.
\end{proof}

\begin{proposition}\label{prop:nd1039}
$\ord_{1039}(2) \nmid M$.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:ordsub1} the order divides $1038=2\cdot3\cdot173$; if it divided $M$ it
would divide $\gcd(M,1038)=6$ (the prime $173>20$ does not divide $M$), forcing
$64 \equiv 1 \pmod{1039}$, false.
\end{proof}

\begin{theorem}[the classes really differ]\label{thm:sep}
\[
1009 \mid \gcd(2^M-1,\ N_{\mathrm{smooth}}), \qquad
\gcd(2^M-1,\ N_{\mathrm{smooth}}) \notin \{1,\ N_{\mathrm{smooth}}\},
\]
\[
\gcd(2^M-1,\ N_{\mathrm{general}}) = 1 .
\]
\end{theorem}

\begin{proof}
Since $1009-1 = 1008 = 2^4\cdot3^2\cdot7$ divides $M$, Theorem~\ref{thm:pm1ok} gives
$1009 \mid \gcd$, so the gcd is $\ne 1$. If the gcd were $N_{\mathrm{smooth}}$ then
$1019 \mid 2^M-1$, hence by Theorem~\ref{thm:criterion} $\ord_{1019}(2)\mid M$,
contradicting Proposition~\ref{prop:nd1019}. (Numerically the gcd is exactly $1009$.)
For the general instance apply Theorem~\ref{thm:pm1fail} with
Propositions~\ref{prop:nd1019} and \ref{prop:nd1039}.
\end{proof}

\begin{theorem}[\dots yet the windows are identical]\label{thm:sameWindow}
$w_{2,N_{\mathrm{smooth}},256} = w_{2,N_{\mathrm{general}},256}$, both equal to the
identity on $\{0,\dots,255\}$; and
$\dc(2,N_{\mathrm{smooth}},256) = \dc(2,N_{\mathrm{general}},256) = 256$.
\end{theorem}

\begin{proof}
Both moduli are divisible by $1019$, so Lemma~\ref{lem:ordred} and
Proposition~\ref{prop:ord1019} give base-$2$ order at least $509>256$; thus
$\min(256,\ord_N(2))=256$ for both, and Theorem~\ref{thm:blind} applies, with
Corollary~\ref{cor:fresh} for the distinct counts. (Numerically the orders are
$256\,536$ and $528\,342$.)
\end{proof}

\begin{corollary}\label{cor:pairAUC}
For every $F$ on pattern words,
$F(w_{2,N_{\mathrm{smooth}},256}) = F(w_{2,N_{\mathrm{general}},256})$; and for real $F$,
\[
\AUC\big(\{N_{\mathrm{smooth}}\},\{N_{\mathrm{general}}\},\ N \mapsto F(w_{2,N,256})\big)
= \tfrac12 .
\]
\end{corollary}

\begin{theorem}[the null, packaged]
For the matched pair above, simultaneously: (i) the $p-1$ method at bound $B=20$
extracts a proper nontrivial divisor of $N_{\mathrm{smooth}}$ and returns the trivial
gcd on $N_{\mathrm{general}}$; (ii) the length-$256$ base-$2$ windows are identical as
combinatorial objects, so every collision feature agrees on the two classes; (iii) hence
every such feature attains $\AUC = 1/2$ exactly.
\end{theorem}

The weakness therefore lives strictly outside the window: it is visible to the
computation $a^M \bmod N$ and to nothing that reads a short prefix.

\section{Blind families at every window length}\label{sec:families}

\begin{definition}
For an odd prime $p$, let $\mathcal{B}_p = \{N : p \mid N,\ N \text{ odd}\}$.
\end{definition}

\begin{proposition}
$\mathcal{B}_p$ is infinite (it contains $p(2k+1)$ for all $k$), and each member is
positive and coprime to $2$.
\end{proposition}

Note $\mathcal{B}_p$ is closed under multiplication by arbitrary odd numbers, so it
contains semiprimes of both smoothness classes in abundance: it is not a family
engineered to dodge the question.

\begin{proposition}\label{prop:inherit}
If $m \le \ord_p(2)$ and $N \in \mathcal{B}_p$ then $m \le \ord_N(2)$.
\end{proposition}

\begin{proof}
Lemma~\ref{lem:ordred} gives $\ord_p(2)\mid \ord_N(2)$, and the latter is positive.
\end{proof}

\begin{theorem}[constant window on a blind family]\label{thm:constwin}
If $m \le \ord_p(2)$, all $N \in \mathcal{B}_p$ share the same length-$m$ pattern word,
and $\dc(2,N,m)=m$ for each.
\end{theorem}

\begin{proof}
Proposition~\ref{prop:inherit} gives $\min(m,\ord_N(2))=m$; apply
Theorem~\ref{thm:blind} and Corollary~\ref{cor:fresh}.
\end{proof}

\subsection{A decidable certificate for large order}

\begin{theorem}[order certificate, monoid form]\label{thm:cert}
Let $g$ be an element of a monoid, $n \ge 1$ with $g^n=1$, and $r$ a prime with
$r \mid n$ and $g^{n/r} \ne 1$. Then $r \mid \ord(g)$; in particular
$r \le \ord(g)$.
\end{theorem}

\begin{proof}
Write $n=sr$. From $g^n=1$, $\ord(g) \mid sr$. If $\ord(g)\mid s$ then
$g^{n/r}=g^s=1$, contradiction; so by Lemma~\ref{lem:primedvd}, $r \mid \ord(g)$. As
$g^n=1$ with $n\ge1$, $\ord(g)>0$, whence $r \le \ord(g)$.
\end{proof}

\begin{corollary}[certificate in $\mathbb{Z}/p\mathbb{Z}$]\label{cor:certzmod}
For $p$ prime, $p \nmid a$, and a prime $r \mid p-1$ with
$a^{(p-1)/r} \not\equiv 1 \pmod p$, one has $r \le \ord_p(a)$.
\end{corollary}

The hypothesis is a single modular exponentiation and equality test --- a cheap,
decidable certificate. With $p=1019$, $r=509$: $1018/509=2$ and $2^2=4\ne1$, giving
$509 \le \ord_{1019}(2)$. With $p=1039$, $r=173$: $1038/173=6$ and $2^6=64\ne1$, giving
$173 \le \ord_{1039}(2)$.

\subsection{Orders grow with the modulus}

\begin{theorem}\label{thm:ordgrow}
For every odd prime $p$, $\;p < 2^{\ord_p(2)}$.
\end{theorem}

\begin{proof}
Let $d=\ord_p(2)\ge1$. By Theorem~\ref{thm:criterion} with $r=p$, $M=d$, we get
$p \mid 2^d-1$, so $p \le 2^d-1 < 2^d$.
\end{proof}

\begin{corollary}\label{cor:existsp}
For every $m$ there is an odd prime $p$ with $\ord_p(2) \ge m$.
\end{corollary}

\begin{proof}
Take a prime $p \ge 2^m+2$; it is odd, and $2^m < p < 2^{\ord_p(2)}$ gives
$m < \ord_p(2)$.
\end{proof}

\begin{theorem}[blind families at every length]\label{thm:blindall}
For every $m$ there is a prime $p$ such that $\mathcal{B}_p$ is infinite, all its members
share one and the same length-$m$ pattern word, and each satisfies $\dc(2,N,m)=m$.
\end{theorem}

\begin{theorem}[No free lunch at every window length]\label{thm:nflall}
For every $m$ there is a prime $p$ with $\mathcal{B}_p$ infinite such that for every real
statistic $F$ of pattern words and all finite nonempty $S,G \subseteq \mathcal{B}_p$,
\[
\AUC\big(S,G,\ N \mapsto F(w_{2,N,m})\big) = \tfrac12 .
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:blindall} plus Theorem~\ref{thm:aucbridge}.
\end{proof}

This is the definitive form of the null: uniform in $m$ (lengthening the window does not
erode the barrier, since a fresh infinite family exists at each length) and uniform in
the labelling.

\section{Mechanism: why the order cannot see smoothness}\label{sec:crt}

Theorem~\ref{thm:truncation} reduces the window to $\min(m,\ord_N(a))$, so the whole
question becomes whether $\ord_N(a)$ knows about the smoothness of $p-1$.

\begin{theorem}[order under CRT]\label{thm:crtord}
For coprime $p,q$: $\;\ord_{pq}(a) = \lcmop\big(\ord_p(a), \ord_q(a)\big)$.
\end{theorem}

\begin{proof}
The Chinese Remainder isomorphism
$\mathbb{Z}/pq\mathbb{Z} \cong \mathbb{Z}/p\mathbb{Z}\times\mathbb{Z}/q\mathbb{Z}$
carries the class of $a$ to the pair of its classes; order is preserved by isomorphism,
and the order of a pair in a product is the lcm of the coordinate orders.
\end{proof}

The decoupling is now transparent. The local order $\ord_p(a)$ divides $p-1$
(Lemma~\ref{lem:ordsub1}), so it is a divisor of the quantity whose \emph{factorization}
defines smoothness; but its \emph{size} --- the only thing the window reads, and then
only truncated at $m$ --- is uninformative about that factorization:
\begin{itemize}[nosep]
\item $p-1$ can be $20$-smooth with large order: $p=1009$, $p-1=2^4\cdot3^2\cdot7$,
$\ord_{1009}(2)=504$;
\item $p-1$ can have a huge prime factor with comparable order: $p=1019$,
$p-1=2\cdot509$, $\ord_{1019}(2)=1018$.
\end{itemize}
Moreover when $m \ll d$ the truncation destroys even the size: $\min(m,d)=m$ regardless.
On the relevant regime the channel is not merely weak but saturated, returning the
constant $m$.

\section{Value-level blindness over a full period}\label{sec:value}

Sections~\ref{sec:pattern}--\ref{sec:crt} concern the collision structure, i.e.\ the
window with values erased. We now record an exact invariance at the level of values.

The base is not canonical: if $\gcd(t,d)=1$ with $d = \ord_N(a)$, then $a^t$ generates
the same cyclic subgroup $\langle a\rangle$ and its orbit is a reindexing of that of $a$.

\begin{lemma}\label{lem:gen}
Let $g$ have finite order $d$ and $\gcd(t,d)=1$. Then $(g^t)^u = g$ for some $u$.
\end{lemma}

\begin{proof}
If $d=1$ then $g=1$ and $u=0$ works. Otherwise choose $u$ with $tu \equiv 1 \pmod d$;
then $(g^t)^u = g^{tu} = g^{tu \bmod d} = g$.
\end{proof}

\begin{lemma}\label{lem:ordpow}
$\ord(g^t) = \ord(g)$ when $\gcd(t,\ord(g))=1$.
\end{lemma}

\begin{theorem}[orbit invariance]\label{thm:orbit}
With $g$ of order $d$ and $\gcd(t,d)=1$,
\[
\{(g^t)^x : 0 \le x < d\} = \{g^x : 0 \le x < d\}.
\]
\end{theorem}

\begin{proof}
($\subseteq$) $(g^t)^x = g^{tx \bmod d}$ with $tx \bmod d < d$. ($\supseteq$) With $u$
from Lemma~\ref{lem:gen}, $g^x = (g^t)^{ux} = (g^t)^{ux \bmod d}$, reducing the exponent
by Lemma~\ref{lem:ordpow}.
\end{proof}

\begin{definition}
$\PV(a,N) = \{a^x \bmod N : 0 \le x < \ord_N(a)\}$, the value set of a full period.
\end{definition}

\begin{theorem}[value-level blindness, full period]\label{thm:valueblind}
Let $N>0$, $\gcd(a,N)=1$, $d=\ord_N(a)$, $\gcd(t,d)=1$. Then
$\PV(a^t,N) = \PV(a,N)$; consequently $F(\PV(a^t,N)) = F(\PV(a,N))$ for every $F$
defined on finite sets of integers.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:ordpow}, $\ord_N(a^t)=d$, so both value sets are indexed by
$\{0,\dots,d-1\}$. Each value is the canonical representative of the corresponding power
of the class of $a$, and representatives are distinct for distinct classes;
Theorem~\ref{thm:orbit} in $(\mathbb{Z}/N\mathbb{Z})^\times$ identifies the two sets of
classes, hence of representatives.
\end{proof}

\begin{theorem}[the only readable scalar]
$|\PV(a,N)| = \ord_N(a)$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:dc} with $m = \ord_N(a)$.
\end{proof}

Thus every symmetric value-level feature of a full period --- histogram, top-bit count,
extremes, moments --- depends only on $(N, \langle a\rangle)$, never on the chosen
generator; and the one scalar the value set exposes is the order, shown
smoothness-agnostic in Section~\ref{sec:crt}.

\begin{remark}[scope]
Theorem~\ref{thm:valueblind} concerns a full period. Value-level features of a
\emph{truncated} window ($m \ll d$) are not covered: the two windows of
Section~\ref{sec:pair} genuinely differ as integer sequences (they carry $122$ and $124$
high bits respectively). Their statistical nullity is an experimental finding, not a
theorem; closing this gap is the sharpest open problem left by this work.
\end{remark}

\section{Genericity: a fact about cyclic prefixes}\label{sec:generic}

Nothing about $\mathbb{Z}/N\mathbb{Z}$ was used beyond finiteness of the order of one
element.

\begin{definition}
For $g$ in a monoid, $\afirst_g(n) = \min\{y : g^y = g^n\}$.
\end{definition}

\begin{theorem}[abstract structure theorem]
If $g$ has finite order then $\afirst_g(n) = n \bmod \ord(g)$ for all $n$.
\end{theorem}

\begin{theorem}[cross-structure blindness]\label{thm:crossblind}
Let $g_1 \in M_1$, $g_2 \in M_2$ be finite-order elements of \emph{arbitrary} monoids
with $\ord(g_1)=\ord(g_2)$. Then $\afirst_{g_1} = \afirst_{g_2}$.
\end{theorem}

No invariant of the ambient structure --- its cardinality, the smoothness of that
cardinality, the arithmetic of the ground ring, the geometry of an underlying curve ---
survives into the orbit prefix. Elliptic-curve point sequences, function-field analogues
and matrix power sequences inherit the blindness verbatim.

\begin{proposition}
For $N>0$ and $\gcd(a,N)=1$, $\first(x) = \afirst_{\bar a}(x)$, where $\bar a$ is the
class of $a$: Section~\ref{sec:pattern} is the $\mathbb{Z}/N\mathbb{Z}$ instance of this
section.
\end{proposition}

\section{Discussion}\label{sec:disc}

\subsection{Which barriers this clears}

\textbf{Symmetry.} Any statistic computable from $N$ alone is symmetric in $p$ and $q$
and cannot by itself name a factor; all our features are $N$-computable.

\smallskip
\noindent\textbf{Class-independent incompressibility.} Theorem~\ref{thm:infobound}
compresses the instance to at most $\log_2(m+1)$ bits independently of any labelling,
and Theorem~\ref{thm:pigeon} makes this a hard non-injectivity statement --- a stronger
and quantitative obstruction.

\smallskip
\noindent\textbf{Known-method collapse.} Theorem~\ref{thm:criterion} localizes the
discriminating information to the single bit $\ord_r(a) \mid M$, whose only known
evaluation route is $a^M \bmod N$: a hypothetical successful statistic would be a
re-implementation of a fifty-year-old attack.

\subsection{What the theorems do and do not say}

They \emph{do} say: for every $m$ there is an infinite family of odd moduli, containing
both smoothness classes, on which every real-valued function of the length-$m$ collision
structure achieves exactly $\AUC=1/2$ under every binary labelling; and that the
weakness is real, characterized exactly by $\ord_r(a)\mid M$.

They \emph{do not} say that no polynomial-time statistic can detect smoothness; that
quantifies over all computations and is out of reach. Nor do they cover truncated
value-level features.

\subsection{Practical reading}

There is no cheap smoothness screen to be had from sequence statistics --- not by adding
features, lengthening the window, or switching model class. Budget spent on such a screen
is better spent on the attack itself, which costs a single exponentiation. Conversely, a
semiprime does not advertise its $p-1$ weakness in any way visible short of a full $p-1$
trial.

\subsection{Open problems}

\begin{enumerate}[label=\arabic*.]
\item \textbf{Value-level blindness for truncated windows.} Extend
Theorem~\ref{thm:valueblind} from full periods to $m \ll d$. A plausible route is an
equidistribution statement for $\{a^x \bmod N\}_{x<m}$ in $[0,N)$ with error uniform over
the class, giving asymptotic rather than exact blindness.
\item \textbf{Sharp constants in the information bound.} The bound $|\mathcal{W}_m|\le
m+1$ is attained. What is the induced distribution over $\mathcal{W}_m$ for a natural
ensemble of semiprimes, and does it differ between classes? This would sharpen the null
from ``exactly $1/2$ on a family'' to ``$1/2+o(1)$ on the ensemble''.
\item \textbf{A symmetry-based unconditional statement.} Identify a group acting on
instances that preserves the class but acts transitively enough on windows to force
blindness; the base action $a \mapsto a^t$ of Theorem~\ref{thm:valueblind} is the
prototype.
\item \textbf{Order certificates at scale.} Systematize
Corollary~\ref{cor:certzmod} into a calculus producing the best lower bound on
$\ord_p(2)$ obtainable from a fixed budget of exponentiations, making the constructions
of Section~\ref{sec:families} effective at cryptographic sizes.
\item \textbf{Beyond $\mathbb{Z}/N\mathbb{Z}$.} By Theorem~\ref{thm:crossblind} the
blindness transfers to elliptic-curve orbits. Does the ECM analogue admit the same exact
treatment, and does the value level behave differently because curve coordinates carry
more structure than residues?
\end{enumerate}

\section{Conclusion}

A short window of the mod-exponential sequence is, structurally, a clock: its collision
pattern is precisely $x \mapsto x \bmod \ord_N(a)$, truncated at the window length.
Consequently at most $m+1$ such patterns exist across all bases and moduli, any two
instances with equal truncated order have literally identical windows, and every real
statistic of such a window scores exactly $\AUC = 1/2$ on an infinite family of moduli
containing both smoothness classes --- at every window length, under every labelling.

Meanwhile the weakness the window fails to see is entirely real: the same computation the
window's terms come from, pushed to the exponent $M = \lcmop(1,\dots,B)$, factors the
smooth instance immediately and fails on the general one. The information exists; it is
confined to one bit, $\ord_r(a)\mid M$; and the only known way to read that bit is to run
the attack.

Negative results are worth stating exactly when they are sharp enough to redirect effort.
This one closes the sequence-level face of the search for cheap factoring self-hints,
identifies precisely why the channel is closed, and leaves a clean, well-posed frontier
at the truncated value level.

